/**
 * Boss quiz: the Student Grade Manager program. 12 questions, 1 easy / 5 medium / 6 hard (10/40/50), ordered easy to hard.
 * Every question combines at least two World 8 lessons (World 6 lists and World 3 conditions are used as plain tools).
 */
const boss = (n: number, difficulty: Diff, concept: string, question: string, explanation: string, hint: string, type: string, data: Record<string, unknown>) =>
  make(base(`w8q-boss-${n}`, L.boss, T.boss, concept, difficulty, question, explanation, hint), type, data);

